pub fn run<'a>(
    config: &'a aws_config::SdkConfig,
    operation: &'a str,
    input: &'a Value,
    options: &'a Options,
) -> core::CommandFuture<'a> {
    Box::pin(async move {
        let mut config = aws_sdk_signin::config::Builder::from(config);
        if let Some(endpoint) = &options.endpoint_url {
            config = config.endpoint_url(endpoint);
        }
        let client = aws_sdk_signin::Client::from_conf(config.build());
        let output = Output::new(options.clone());
        let command: core::CommandFuture<'_> = match operation {
            "create_o_auth2_token" => Box::pin(call_create_o_auth2_token(&client, input, &output)),
            "create_o_auth2_token_with_iam" => {
                Box::pin(call_create_o_auth2_token_with_iam(&client, input, &output))
            }
            "delete_console_authorization_configuration" => Box::pin(
                call_delete_console_authorization_configuration(&client, input, &output),
            ),
            "delete_resource_permission_statement" => Box::pin(
                call_delete_resource_permission_statement(&client, input, &output),
            ),
            "get_console_authorization_configuration" => Box::pin(
                call_get_console_authorization_configuration(&client, input, &output),
            ),
            "get_resource_policy" => Box::pin(call_get_resource_policy(&client, input, &output)),
            "introspect_o_auth2_token_with_iam" => Box::pin(
                call_introspect_o_auth2_token_with_iam(&client, input, &output),
            ),
            "list_resource_permission_statements" => Box::pin(
                call_list_resource_permission_statements(&client, input, &output),
            ),
            "put_console_authorization_configuration" => Box::pin(
                call_put_console_authorization_configuration(&client, input, &output),
            ),
            "put_resource_permission_statement" => Box::pin(
                call_put_resource_permission_statement(&client, input, &output),
            ),
            "revoke_o_auth2_token_with_iam" => {
                Box::pin(call_revoke_o_auth2_token_with_iam(&client, input, &output))
            }
            _ => return Err(CliError::input(format!("unknown operation: {operation}"))),
        };
        command
            .await
            .map_err(|error| error.context("signin", operation))
    })
}
